definition.raw:
we define the jump of the vector field $v$ across $e$ as
\begin{equation}\label{jump}
\[v\]_e=v|_{K^+} \cdot n_{K^+} + v|_{K^-}  \cdot n_{K^-}, 
\end{equation}
and its average on $e$ as
\begin{equation}\label{average}
 \{\!\{v\}\!\}_e= \frac{1}{2}(v|_{K^+}  + v|_{K^-} ).

We define 
$$
P_h u = \hat{P}_h(u-G) + I_h G,
$$
where $I_h$ denotes the canonical Lagrange interpolant operator into $V_h$.
Then
$P_h u = I_h u$ on $\partial \Omega$ and
\begin{equation}\label{2grid-proj-def}
A'(u;P_h u - u, \phi) = A'(u;I_h G - G, \phi) ,~ \forall \phi \in V_h \cap H_0^1(\Omega).
\end{equation}
Put $w=u-G$. Since $w=0$ on $\partial \Omega$ and $w$ is smooth, we have \cite[Corollary 8.1.12]{Brenner08}
\begin{equation*}
||w- \hat{P}_h(w)||_{W^{1,\infty}} \leq C h^{k} ||w||_{W^{k+1,\infty}}, \ \text{for } w \in W^{k+1,\infty}(\Omega), 
w=0 \text{ on } \partial \Omega. 
\end{equation*}
Therefore
\begin{align*}
||u-P_h u||_{W^{1,\infty}} & = ||w+ G - \hat{P}_h w-I_h G ||_{W^{1,\infty}} \\
& \leq ||w- \hat{P}_h w||_{W^{1,\infty}} +||G-I_h G||_{W^{1,\infty}}.
\end{align*}
It thus follows from the approximation properties of $I_h$ that
\begin{equation}
||u-P_h u||_{W^{1,\infty}} \leq C h^{k} ||u||_{W^{k+1,\infty}} \equiv C_1 h^k, \ \text{for } u \in W^{k+1,\infty}(\Omega).  \label{2grid-proj1}  
\end{equation}

By an inverse estimate, \eqref{2grid-proj1}, and the approximation properties of $I_h$, we have
\begin{align*}
||u-P_h u||_{W^{2,\infty}(\mathcal{T}_h)} &\leq ||u-I_h u ||_{W^{2,\infty}(\mathcal{T}_h)} + ||I_h u -P_h u||_{W^{2,\infty}(\mathcal{T}_h)} \\
& \leq C h^{k-1} ||u||_{W^{k+1,\infty}}  + C h^{-1} \big(  ||I_h u - u||_{W^{1,\infty}} +  || u-P_h u||_{W^{1,\infty}}  \big),
\end{align*}
that is
\begin{align} 
||u-P_h u||_{W^{2,\infty}(\mathcal{T}_h)} &\leq C h^{k-1} ||u||_{W^{k+1,\infty}} \label{2grid-proj2}. 
\end{align}





Following \cite{Xu1996}, we will obtain pointwise estimates via the use of discrete Green's functions. For $z\in \Omega \setminus \cup_{K \in \mathcal{T}_h}\partial K$, let $g^z_{h,i} \in V_h \cap H_0^1(\Omega)$, $i=1,2$ be defined by:
\begin{equation}\label{2grid-green1}
A'(u; g^z_{h,i},\phi)=\frac{\partial \phi}{\partial x_i}(z),  \quad \forall \phi \in V_h \cap H_0^1(\Omega),
\end{equation}
and let $G^z_h$ be defined by
\begin{equation}\label{2grid-green2}
A'(u;G^z_h,\phi) = \phi (z), \quad \forall \phi \in V_h \cap H_0^1(\Omega).
\end{equation}
We have for $h$ sufficiently small



\begin{equation}\label{2grid-W11greenbound}
\|g^z_{h,i}\|_{W^{1,1}} \leq C |\ln h|,
\end{equation}
and
\begin{align*} 
\|G^z_h\|_{L^{2}} \leq C,
\end{align*}
where the constant $C$ is independent of $z$. In the case $\cof D^2 u$ is the identity matrix, the proof is given in \cite[Lemmas 2.1 and 3.3]{ThomeeXuZhang}. The proof of the general case is similar \cite{Malitz-thesis}. Moreover
we have \cite{Malitz-thesis}, see also \cite[Exercise 8.x.19]{Brenner08},
\begin{align} \label{green-0}
\|G^z_h\|_{W^{1,1}} \leq C|\ln h|.
\end{align}





It is enough to prove that $|G^z_h |_{W^{1,1}} \leq C|\ln h|$ which follows from the bound
$| G^z_h |_{W^{1,2}} \leq C | \ln h|^{\frac{1}{2}} $ and H\"older's inequality. 
By the discrete Sobolev inequality \cite[(4.9.2)]{Brenner08} and the coercivity of the form $A'(u; .,.)$, we have for $h$ sufficiently small
\begin{align*}
| A'(u;G^z_h,G^z_h) | = | G^z_h (z)| \leq || G^z_h ||_{L^{\infty}} \leq C  | \ln h|^{\frac{1}{2}} || G^z_h ||_{H^{1}} \leq C  | \ln h|^{\frac{1}{2}} 
|A'(u;G^z_h,G^z_h)|^{\frac{1}{2}}. 
\end{align*}
It follows that
$$
| G^z_h |_{W^{1,2}}  \leq C |A'(u;G^z_h,G^z_h)|^{\frac{1}{2}} \leq C  | \ln h|^{\frac{1}{2}},
$$
giving the claimed bound.

We define a nonlinear operator $\Phi: V_h \to V_h$ by  $ v_h = \Phi( v_h)$ on $\partial \Omega$ and
\begin{equation} \label{Phi-def}
A'(u; v_h-\Phi( v_h),\phi) = A_{}( v_h,\phi), \quad \forall \phi \in V_h \cap H_0^1(\Omega).

theorem.raw:
\label{2grid-imp-thm}
Problem \eqref{IP-abstract} has a unique solution $u_h$ in $B_h$ for $k \geq 3$, $h$ sufficiently small and
$$||u-u_h||_{W^{1,\infty}} \leq C h^{k} |\ln h |.$$

\label{2grid-imp2-thm}
Problem \eqref{IP-abstract} has a unique solution $u_h$ in $B_h$ for $k \geq 3$, $h$ sufficiently small and
$$||u-u_h||_{H^{1}} \leq C h^{k}. $$

We have the estimate
\begin{equation}\label{2grid-conv-lemma}
||u^h-u_h||_{H^{1}} \leq C h^k,
\end{equation}
for $k \geq 3, H=h^{\lambda}, 1> \lambda>  1/2 + (2+\epsilon)/(2k), 0< \epsilon <1$ and $h$ sufficiently small.

lemma.raw:
\label{interior-penalty-frechet-lemma}
For $v, w \in H^2(K)$ for all $K \in \mathcal{T}_h$ and $\phi \in H^1_0(\Omega)$, we have
\begin{align}\label{IP-frechet}
\begin{split}
A'(w;v,\phi) &  = \sum_{K \in \mathcal{T}_h} \int_{K }\big( (\cof  D^2 w)  D v \big) \cdot D \phi \,d x \\
& \quad - \sum_{e \in \mathcal{E}_h^i }
\int_e \[(\cof  D^2 w)\] \{\!\{D v\}\!\} \phi  \,d s 
 + \sum_{e \in \mathcal{E}_h^i } \int_e \[\{\!\{\cof D^2 v \}\!\} D w \] \phi
\,d s,
\end{split}
\end{align}
and
\begin{align} \label{rdef1}
R(w;v,\phi) = -\sum_{K \in \mathcal{T}_h}  \int_{K} (\det D^2v)\phi\,d x + \sum_{e \in \mathcal{E}_h^i } \int_e \[\{\!\{\cof D^2 v \}\!\} D v \] \phi\,d s.
\end{align}
In particular, for $u \in C^3(\Omega)$, \eqref{Frechet-at-u} holds.

We have for $\phi \in H_0^{1}(\Omega)$ and $v, w \in H^2(K)$ for all $K \in \mathcal{T}_h$,
\begin{multline} \label{R1-simple}

R(w;v,\phi)  = \frac{1}{2} \sum_{K \in \mathcal{T}_h}  \int_K [(\cof D^2 v) D v ]  \cdot D \phi \,d x \\
-\frac{1}{2}  \sum_{e \in \mathcal{E}_h^i } \int_e \[(\cof D^2 v) \] \{\!\{ D v \}\!\} \phi \,d s 
 + \frac{1}{2} \sum_{e \in \mathcal{E}_h^i } \int_e \[ \{\!\{\cof D^2 v \}\!\} D v \] \phi\,d s.

\end{multline}

proof.raw:
Using \eqref{det1} and integration by parts
\begin{multline*}
 \int_{K} (\det D^2 v ) \phi \,d x = \frac{1}{2}  \int_{K} (\cof D^2 v ): (D^2 v) \, \phi \,d x = \frac{1}{2}  \int_{K} \operatorname{div}\big((\cof D^2 v) D v ) \phi \,d x
 \\
 =-  \frac{1}{2} \int_K [(\cof D^2 v) D v ] \cdot D \phi \,d x + \frac{1}{2}  \int_{\partial K} \big[ (\cof D^2 v) D v \big] \cdot n_K \phi \,d s.
\end{multline*}
By definition of jump and since $\phi=0$ on $\partial \Omega$, we have
\begin{align}
\sum_{K \in \mathcal{T}_h} \int_{\partial K} \big( (\cof D^2 v) D v \big) \cdot n_K \phi \,d s & = \sum_{e \in \mathcal{E}_h^i } \int_e \[(\cof D^2 v) D v \] \phi \,d s  \label{part-22}.
\end{align}
We conclude that
\begin{multline*}
R(w;v,\phi) = \frac{1}{2} \sum_{K \in \mathcal{T}_h}  \int_K [(\cof D^2 v) D v ] \cdot D \phi \,d x 
-\frac{1}{2}  \sum_{e \in \mathcal{E}_h^i } \int_e \[(\cof D^2 v) D v \] \phi \,d s \\
+ \sum_{e \in \mathcal{E}_h^i } \int_e \[\{\!\{\cof D^2 v \}\!\} D v \] \phi\,d s.
\end{multline*}
Therefore, using \eqref{jumpaverage} to expand the term $\[(\cof D^2 v) D v \] $ we obtain \eqref{R1-simple}.

For $v_h \in B_h$, 
we have using \eqref{Phi-def} and \eqref{2grid-proj-def}
\begin{align*}
\begin{split}
A'(u;\Phi( v_h)- P_h u,\phi) 
&= A'(u;\Phi( v_h)-  v_h,\phi)+A'(u; v_h- P_h u,\phi) \\
&= -A_{}( v_h,\phi) + A'(u; v_h-  u,\phi) +  A'(u; u - P_h u,\phi) \\
&= -A_{}( v_h,\phi) + A'(u; v_h-  u,\phi) - A'(u;I_h G - G, \phi). 
\end{split}
\end{align*}
By definition of the residual \eqref{rdef0}, and since $A(u,\phi)=0$, we have
$$
-A_{}( v_h,\phi) + A'(u; v_h-  u,\phi) = A(u,\phi) -A_{}( v_h,\phi) + A'(u; v_h-  u,\phi) = -R(u;v_h-u,\phi).
$$
We conclude that
\begin{align} \label{expr-inv}
A'(u;\Phi( v_h)- P_h u,\phi) = -R(u;v_h-u,\phi) - A'(u;I_h G - G, \phi).
\end{align}
Therefore, using \eqref{R1-simple}, \eqref{w11-phi} and \eqref{Frechet-at-u}, we have 
\begin{multline*}
| A'(u;\Phi( v_h)- P_h u,\phi)   | \leq C || v_h-u ||_{W^{2,\infty}(\mathcal{T}_h)}  ||  v_h-u ||_{W^{1,\infty}}  || \phi ||_{W^{1,1}} \\ +C  ||  v_h-u ||_{W^{2,\infty}(\mathcal{T}_h)}  ||  v_h-u ||_{W^{1,\infty}} 
 \sum_{e \in \mathcal{E}_h^i } || \phi ||_{L^1(e)} +  |A'(u;I_h G - G, \phi) | \\
 \leq C h^{-1} || v_h-u ||_{W^{2,\infty}(\mathcal{T}_h)}  ||  v_h-u ||_{W^{1,\infty}}  || \phi ||_{W^{1,1}} + |A'(u;I_h G - G, \phi)|.
\end{multline*}

By definition of $B_h$,  $||v_h-u||_{W^{1,\infty}} \leq C h^{k} |\ln h |$. 
Moreover, by triangle inequality, \eqref{2grid-proj2}
and an inverse estimate
$||v_h-u||_{W^{2,\infty}(\mathcal{T}_h)} \leq ||v_h-P_h u||_{W^{2,\infty}(\mathcal{T}_h)} + ||P_h u-u||_{W^{2,\infty}(\mathcal{T}_h)} \leq C h^{k-1} |\ln h | + C h^{k-1}  \leq C h^{k-1} |\ln h | $. Thus
\begin{multline*}
| A'(u;\Phi( v_h)- P_h u,\phi)   | \leq C h^{k-2}  |\ln h | \, || \phi ||_{W^{1,1}}   h^{k} |\ln h | + |A'(u;I_h G - G, \phi)| \\
\leq (C h^{k-2} |\ln h |^2  ) h^{k} || \phi ||_{W^{1,1}} + | A'(u;I_h G - G, \phi)| .
\end{multline*}
Taking $\phi=g^z_{h,i}$ with the estimate \eqref{2grid-W11greenbound}, and taking $\phi=G^z_h$ with the estimate \eqref{green-0}, we obtain using the definition of $C_4$
$$
\|\Phi( v_h)- P_h u\|_{W^{1,\infty}} \leq   (C h^{k-2} |\ln h |^2 + C_4 ) h^{k } |\ln h|.
$$
Since $C  h^{k-2} |\ln h |^2  \leq C_4$ for $h$ sufficiently small and $k \geq 3$, we get
$\|\Phi( v_h)- P_h u\|_{W^{1,\infty}} \leq 2 C_4  h^{k } |\ln h|$.
By triangular inequality and \eqref{2grid-proj1}, the result follows.

The proof is based on the expression \eqref{expr-con} of $A'(u;\Phi( v_h)- \Phi( w_h),\phi)$ derived in the proof of Lemma \ref{contraction} and the expression \eqref{expr-inv} of $A'(u; \Phi( v_h)- P_h u,\phi )$ derived in the proof of Lemma \ref{invariant}. 
Since $\Phi(u_h) = u_h$, we have
\begin{align} \label{u-p-01}
\begin{split}
A'(u; u_h - P_h u,\phi) & = A'(u; \Phi(u_h) - P_h u,\phi) \\
& =  A'(u; \Phi(u_h) - \Phi(P_h u),\phi)  +  A'(u; \Phi(P_h u) - P_h u,\phi). 
\end{split}
\end{align}
In view of \eqref{expr-con}, we obtain 
\begin{multline} \label{u-p-02}
| A'(u; \Phi(u_h) - \Phi(P_h u),\phi)| \leq C  ||u_h-P_h u ||_{W^{2,\infty}(\mathcal{T}_h)}  ||P_h u-u ||_{H^{1}} ||\phi||_{H^1} + \\
C ||u_h- u ||_{W^{2,\infty}(\mathcal{T}_h)}  || u_h- P_h u ||_{H^{1}} ||\phi||_{H^1} + C  ||u_h-P_h u ||_{W^{2,\infty}(\mathcal{T}_h)} 
\sum_{K \in \mathcal{T}_h } | P_h u - u |_{H^{1}(\partial K)} ||\phi||_{L^2(\partial K)} \\
+  C  ||u_h- u ||_{W^{2,\infty}(\mathcal{T}_h)} 
\sum_{K \in \mathcal{T}_h } || P_h u - u_h ||_{H^{1}(\partial K)} ||\phi||_{L^2(\partial K)}.
\end{multline}
By an inverse estimate, Theorem \ref{2grid-imp-thm}, triangle inequality and \eqref{2grid-proj1}, we have $||u_h-P_h u ||_{W^{2,\infty}(\mathcal{T}_h)} \leq
C h^{k-1} | \ln h| $. Similarly, using \eqref{2grid-proj2}, we have $||u_h- u ||_{W^{2,\infty}(\mathcal{T}_h)} \leq C h^{k-1} | \ln h|$.  
Next, by the scaled trace inverse inequality \eqref{trace-inverse} 
and Cauchy-Schwarz inequality
\begin{multline} \label{u-p-03}
 \sum_{K \in \mathcal{T}_h } || P_h u - u_h ||_{H^{1}(\partial K)} ||\phi||_{L^2(\partial K)}  \leq C h^{-1} 
  \sum_{K \in \mathcal{T}_h } || P_h u - u_h ||_{H^{1}( K)} ||\phi||_{H^1( K)} \\
    \leq C h^{-1}  || P_h u - u_h ||_{H^{1}} ||\phi||_{H^1}.
\end{multline}


By \eqref{bramble}, an inverse estimate and \eqref{local-nodal-interpolant} 
\begin{align*}
| P_h u - u |_{H^{1}(\partial K)}  & \leq | P_h u - I_h u |_{H^{1}(\partial K)} + | I_h u - u |_{H^{1}(\partial K)}  \\
& \leq C h^{-\frac{1}{2}}  | P_h u - I_h u |_{H^{1}(K)} + C h^{k-\frac{1}{2}} ||u||_{H^{k+1}(K)} \\
& \leq  C h^{-\frac{1}{2}}  | P_h u -  u |_{H^{1}(K)} +  C h^{-\frac{1}{2}}  | u - I_h u |_{H^{1}(K)} + C h^{k-\frac{1}{2}} ||u||_{H^{k+1}(K)}\\
& \leq C h^{-\frac{1}{2}}  | P_h u -  u |_{H^{1}(K)}  + C h^{k-\frac{1}{2}} ||u||_{H^{k+1}(K)}.
\end{align*}
We have $|| P_h u - u ||_{H^{1}} \leq C h^k ||u||_{H^{k+1}}$. This follows from \cite[Theorem 5.4.4]{Brenner08} in the case of homogeneous boundary conditions. The proof of the general case is similar to \eqref{2grid-proj1}.
Thus
$$
\bigg( \sum_{K \in \mathcal{T}_h} | P_h u - u |_{H^{1}(\partial K)} ^2 \bigg)^{\frac{1}{2}} \leq 
C h^{-\frac{1}{2}}  | P_h u -  u |_{H^{1}}  + C h^{k-\frac{1}{2}} ||u||_{H^{k+1}} \leq C h^{k-\frac{1}{2}} ||u||_{H^{k+1}}.
$$ 
As with \eqref{u-p-03}, by \eqref{trace-inverse} and Cauchy-Schwarz inequality, it follows that
\begin{multline} \label{u-p-04}
 \sum_{K \in \mathcal{T}_h } | P_h u - u |_{H^{1}(\partial K)} ||\phi||_{L^2(\partial K)} \leq 
 C h^{-\frac{1}{2} } \sum_{K \in \mathcal{T}_h } | P_h u - u |_{H^{1}(\partial K)} ||\phi||_{H^1( K)} \\

  \leq 
  C h^{k-1} ||u||_{H^{k+1} } ||\phi||_{H^1}. 
\end{multline}
We conclude from \eqref{u-p-02}--\eqref{u-p-04} that
\begin{multline*} 
| A'(u; \Phi(u_h) - \Phi(P_h u),\phi)| \leq C h^{k-1} | \ln h| \, || P_h u - u ||_{H^{1}} ||\phi||_{H^1} \\
+ C h^{k-1} | \ln h| \, ||  u_h - P_h u  ||_{H^{1}} ||\phi||_{H^1} 
+  C h^{k-1}  ||u_h - P_h u ||_{W^{2,\infty}} ||\phi||_{H^1}  \\
+ C h^{k-2} | \ln h| \, ||  u_h - P_h u  ||_{H^{1}} ||\phi||_{H^1}.
\end{multline*}
Therefore since by Theorem \ref{2grid-imp-thm} we have the suboptimal estimate $ ||  u_h - P_h u  ||_{H^{1}} \leq C ||u_h - P_h u ||_{W^{1,\infty}}  \leq C h^k | \ln h| $
\begin{multline} \label{u-p-05}
| A'(u; \Phi(u_h) - \Phi(P_h u),\phi)| \leq  C h^{k-1} | \ln h|   h^k ||\phi||_{H^1}  + C h^{k-1} | \ln h|^2   h^k ||\phi||_{H^1} \\
 + C h^{k-2} | \ln h| h^k ||\phi||_{H^1} + C h^{k-2} | \ln h|^2 h^k ||\phi||_{H^1}\\
 \leq C h^{k-2} | \ln h|^2 h^k ||\phi||_{H^1} \leq C h^k ||\phi||_{H^1},
\end{multline}
for $k \geq 3$. By \eqref{expr-inv}, we have
$$
 A'(u; \Phi(P_h u) - P_h u,\phi) = -R(u;P_h u-u,\phi) + A'(u;I_h G - G, \phi).
$$
Using \eqref{R1-simple} and inverse estimates as for \eqref{u-p-04}, we obtain
\begin{multline*} 
| A'(u; \Phi(P_h u) - P_h u,\phi) | \leq C ||P_h u - u ||_{W^{2,\infty}(\mathcal{T}_h)} ||P_h u - u ||_{H^{1}}  ||\phi||_{H^1} \\
+ C  h^{-1} ||P_h u - u ||_{W^{2,\infty}(\mathcal{T}_h)}  || P_h u - u ||_{H^{1}} ||\phi||_{H^1} 
+C\|I_hG-G\|_{H^1}\|\phi\|_{H^1},
\end{multline*}
i.e.
\begin{multline} \label{u-p-06}
| A'(u; \Phi(P_h u) - P_h u,\phi) | \leq C ( h^{k-1} |\ln h| h^k + h^{k-2} |\ln h| h^k + h^k ) ||\phi||_{H^1} \\ \leq C h^k ||\phi||_{H^1}, 
\end{multline}
for $k \geq 3$. Taking $\phi = u_h - P_h u $ in \eqref{u-p-01} and using \eqref{u-p-05} and \eqref{u-p-06}, we get from Poincar\'e's inequality
and $k \geq 3$, for $h$ sufficiently small
$$
 ||  u_h - P_h u  ||_{H^{1}} \leq Ch^k.
$$
This completes the proof by a triangle inequality.

By definition of the two-grid algorithm, the definition of the residual \eqref{rdef0}, and $A(u_h,\phi)=0$ for $\phi \in V_h\cap  W^{1,\infty}_0(\Omega)$, we have

\begin{align*}
A'(u_H; u_h-u^h, \phi)&= A'(u_H; u_h-u_H, \phi) + A'(u_H; u_H-u^h, \phi) \\
& = A'(u_H; u_h-u_H, \phi) + A(u_H,\phi) \\
& = A(u_h,\phi) - R(u_H;u_h-u_H,\phi) = - R(u_H;u_h-u_H,\phi). 
\end{align*}




It follows that
\begin{align*}
A'(u; u_h-u^h, \phi)& = A'(u-u_H; u_h-u^h, \phi) + A'(u_H; u_h-u^h, \phi) \\
& = A'(u-u_H; u_h-u^h, \phi) - R(u_H;u_h-u_H,\phi). 
\end{align*}
With arguments similar to the ones used in the proof of Theorem \ref{2grid-imp2-thm}, we have
\begin{multline} \label{u-p-066}
| A'(u; u_h-u^h, \phi) | \leq C  || u - u_H ||_{W^{2,\infty}(\mathcal{T}_h)}  || u_h - u^h ||_{H^{1}} ||\phi||_{H^1} \\
+ C h^{-1} || u - u_H ||_{W^{2,\infty}(\mathcal{T}_h)}  || u_h - u^h ||_{H^{1}} ||\phi||_{H^1} 
+ C || \phi ||_{L^{\infty}} \sum_{K \in \mathcal{T}_h } | u - u_H |_{H^{1}(\partial K)} ||  u_h - u^h ||_{H^2(\partial K)}\\
+ |R(u_H;u_h-u_H,\phi)|.
\end{multline}
But, using \eqref{bramble}, \eqref{local-nodal-interpolant} and an inverse estimate
\begin{align*}
| u - u_H |_{H^{1}(\partial K)} & \leq | u - I_H u |_{H^{1}(\partial K)} + | I_H u - u_H |_{H^{1}(\partial K)} \\
& \leq C H^{k-\frac{1}{2}} ||u||_{H^{k+1}(K)} + C H^{-\frac{1}{2}}  | I_H u - u_H |_{H^{1}( K)} \\
& \leq C H^{k-\frac{1}{2}} ||u||_{H^{k+1}(K)} + C H^{-\frac{1}{2}}  | I_H u - u |_{H^{1}( K)} + C H^{-\frac{1}{2}}  | u - u_H |_{H^{1} ( K)}. 

\end{align*}
It follows that
$$
\bigg( \sum_{K \in \mathcal{T}_h } | u - u_H |^2_{H^{1}(\partial K)} \bigg)^{\frac{1}{2}} \leq C H^{k-\frac{1}{2}} ||u||_{H^{k+1}} + C H^{-\frac{1}{2}}  | I_H u - u |_{H^{1}} + C H^{-\frac{1}{2}}  | u - u_H |_{H^{1} }.
$$
We therefore obtain from \eqref{nodal-interpolant} and Theorem \ref{2grid-imp2-thm}
$$
\bigg( \sum_{K \in \mathcal{T}_h } | u - u_H |^2_{H^{1}(\partial K)} \bigg)^{\frac{1}{2}} \leq C H^{k-\frac{1}{2}} ||u||_{H^{k+1}}. 
$$
By Cauchy-Schwarz's inequality, \eqref{trace-inverse} and an inverse estimate, it follows that
$$
\sum_{K \in \mathcal{T}_h } | u - u_H |_{H^{1}(\partial K)} ||  u_h - u^h ||_{H^2(\partial K)} \leq C h^{- \frac{3}{2}}  H^{k-\frac{1}{2}} ||u||_{H^{k+1}}
 || u_h - u^h ||_{H^{1}}. 
$$
