\end{equation}
A fixed point of $\Phi$ is a solution of the nonlinear finite element problem \eqref{IP-abstract}. We note that by \eqref{nodal-interpolant},  \eqref{2grid-W11greenbound} and \eqref{green-0}
\begin{align*}
| A'(u;I_h G - G, G^z_h) | & \leq C_2 h^k | \ln h| \\
| A'(u;I_h G - G, g^z_{h,i}) | & \leq C_3 h^k | \ln h|.
\end{align*}
We then define $C_4= \max\{ C_1, C_2, C_3 \}$ where the constant $C_1$ is defined in \eqref{2grid-proj1}.

Consider the closed set
\begin{equation}\label{2grid-ball}
B_h = \{ v \in V_h: v=g_h \text{ on } \partial \Omega, ||v-u||_{W^{1,\infty}} \leq 3 C_4 h^{k} |\ln h |\}.
\end{equation}
 By  \eqref{2grid-proj1} $P_h u \in B_h$ and hence $B_h$ is non-empty.

