$$
\bigg( \sum_{K \in \mathcal{T}_h } | u - u_H |^2_{H^{1}(\partial K)} \bigg)^{\frac{1}{2}} \leq C H^{k-\frac{1}{2}} ||u||_{H^{k+1}}. 
$$
By Cauchy-Schwarz's inequality, \eqref{trace-inverse} and an inverse estimate, it follows that
$$
\sum_{K \in \mathcal{T}_h } | u - u_H |_{H^{1}(\partial K)} ||  u_h - u^h ||_{H^2(\partial K)} \leq C h^{- \frac{3}{2}}  H^{k-\frac{1}{2}} ||u||_{H^{k+1}}
 || u_h - u^h ||_{H^{1}}. 
$$
Therefore, since $|| u - u_H ||_{W^{2,\infty}(\mathcal{T}_h)} \leq C H^{k-1} |\ln H|$ and by the discrete Sobolev inequality, c.f.  \cite{Bramble86},
$|| \phi ||_{L^{\infty}}  \leq C (1+ | \ln h|^{ 1/2 }) ||\phi||_{H^1}$, we obtain from \eqref{u-p-066} 
\begin{multline} \label{u-p-07}
| A'(u; u_h-u^h, \phi) | \leq C h^{-1} || u - u_H ||_{W^{2,\infty}(\mathcal{T}_h)}  || u_h - u^h ||_{H^{1}} ||\phi||_{H^1} \\
+ C H^{k-\frac{1}{2}} h^{- \frac{3}{2}}   | \ln h| \, || u_h - u^h ||_{H^{1}}  ||u||_{H^{k+1} } ||\phi||_{H^1} + |R(u_H;u_h-u_H,\phi)| \\
\leq C h^{-1} H^{k-1} |\ln H| \, || u_h - u^h ||_{H^{1}} ||\phi||_{H^1} 
+ C H^{k-\frac{1}{2}} h^{- \frac{3}{2}} |\ln h| \,   || u_h - u^h ||_{H^{1}} ||\phi||_{H^1} \\
+ |R(u_H;u_h-u_H,\phi)|. 
\end{multline}
Using \eqref{R1-simple} and 
the trace estimates \eqref{trace-inverse} and \eqref{trace-estimate}, we have
\begin{multline} \label{u-p-08}
 |R(u_H;u_h-u_H,\phi)| \leq C  || u_h - u_H ||_{W^{2,\infty}(\mathcal{T}_h)}  || u_h - u_H ||_{H^{1}} ||\phi||_{H^1} \\
+ C h^{-1} || u_h - u_H ||_{W^{2,\infty}(\mathcal{T}_h)}  || u_h - u_H ||_{H^{1}} ||\phi||_{H^1}  \\
\leq C h^{-2} || u_h - u_H ||_{W^{1,\infty}}  || u_h - u_H ||_{H^{1}} ||\phi||_{H^1}. 
\end{multline}
Taking $\phi = u_h - u^h $ in \eqref{u-p-07} and using \eqref{u-p-08}, we get from Poincar\'e's inequality, Theorems \ref{2grid-imp-thm} and \ref{2grid-imp2-thm}
for $k \geq 3$ and $h$ sufficiently small
\begin{multline*}
|| u_h - u^h ||_{H^{1}} \leq C (h^{-1} H^{k-1} |\ln H| + H^{k-\frac{1}{2}} h^{- \frac{3}{2}} |\ln h|  ) || u_h - u^h ||_{H^{1}} \\
+C h^{-2} (h^{k} |\ln h | + H^{k} |\ln H |) (h^k+H^k).
\end{multline*}
We conclude that for $H=h^{\lambda}$, $\lambda > \max \{1/(k-1), 3/(2k-1) \} = 3/(2k-1)$ and $k \geq 3$, 
$$
|| u_h - u^h ||_{H^{1}} \leq C h^{-2}  |\ln H \, | H^{2k}.
$$
We therefore get $||u^h-u_h||_{H^{1}} \leq C h^k$ provided $\lambda >  3/(2k-1)$ and $2 \lambda k -2- \epsilon > k$ for some $\epsilon \in (0,1) $, that is 
$\lambda >  \max \{ (k+2+ \epsilon)/(2k), 3/(2k-1) \} = 1/2 + (2+\epsilon)/(2k)$ for $k \geq 3$. 
\end{proof}

{\bf Two-grid algorithm}

\begin{enumerate} \label{2grid-alg1}
\item[1.]

find $u_H \in V_H$, $u_H=g_H$ on $\partial \Omega$, and $A(u_H,\chi) = 0, ~ \forall ~\chi \in  V_H\cap H^1_0(\Omega)$,
\item[2.]  find $u^h \in V_h$, $u^h=g_h$ on $\partial \Omega$, and $A'(u_H;u^h-u_H,\phi)=-A(u_H,\phi),  ~\forall ~\phi \in  V_h\cap H^1_0(\Omega)$.
\end{enumerate}

